import{_ as s,c as n,o as e,ag as i}from"./chunks/framework.CQuhCYrb.js";const b=JSON.parse('{"title":"Kismet","description":"","frontmatter":{"title":"Kismet"},"headers":[],"relativePath":"general/kismet.md","filePath":"general/kismet.md","lastUpdated":null}'),l={name:"general/kismet.md"};function p(r,a,t,o,c,d){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="kismet" tabindex="-1">Kismet <a class="header-anchor" href="#kismet" aria-label="Permalink to &quot;Kismet&quot;">​</a></h1><h2 id="what-is-kismet" tabindex="-1">What Is Kismet <a class="header-anchor" href="#what-is-kismet" aria-label="Permalink to &quot;What Is Kismet&quot;">​</a></h2><p>Kismet is a wireless network and device detector, sniffer, wardriving tool, and WIDS (wireless intrusion detection) framework.</p><p>Kismet works with Wi-Fi and Bluetooth interfaces, SDR (software-defined radio) hardware like the RTLSDR, and other specialized capture hardware.</p><p>Kismet operates on Linux, macOS, and to a degree on Windows 10 under the WSL framework. On Linux, it supports most Wi-Fi cards, Bluetooth interfaces, and other hardware devices. On macOS, it works with built-in Wi-Fi interfaces, while on Windows 10, it supports remote captures.</p><p>Kismet operates passively (except for specific features like Bluetooth scanning). It is not typically an attack tool but focuses on collecting and analyzing wireless data. Logs generated by Kismet, such as PCAP files and handshakes, can be used with tools like Hashcat or Aircrack-NG for further analysis.</p><p>See the <a href="https://forums.kali.org/archived/tags.php?tag=kismet" target="_blank" rel="noreferrer">Kali Forum about Kismet</a></p><h3 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h3><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. Remove Kismet if installed</span></span>
<span class="line"><span>sudo apt autoremove kismet</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Install dependencies</span></span>
<span class="line"><span>sudo apt install -y build-essential git libwebsockets-dev pkg-config zlib1g-dev \\</span></span>
<span class="line"><span>libnl-3-dev libnl-genl-3-dev libcap-dev libpcap-dev libnm-dev libdw-dev \\</span></span>
<span class="line"><span>libsqlite3-dev libprotobuf-dev libprotobuf-c-dev protobuf-compiler protobuf-c-compiler \\</span></span>
<span class="line"><span>libsensors4-dev libusb-1.0-0-dev python3 python3-setuptools python3-protobuf \\</span></span>
<span class="line"><span>python3-requests python3-numpy python3-serial python3-usb python3-dev python3-websockets \\</span></span>
<span class="line"><span>librtlsdr0 libubertooth-dev libbtbb-dev gpsd gpsd-clients</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Clone and build Kismet</span></span>
<span class="line"><span>git clone https://www.kismetwireless.net/git/kismet.git</span></span>
<span class="line"><span>cd kismet</span></span>
<span class="line"><span>./configure</span></span>
<span class="line"><span>make -j$(nproc)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. Install Xcode (if not installed)</span></span>
<span class="line"><span>xcode-select -p 1&gt;/dev/null || xcode-select --install</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Install Homebrew and update</span></span>
<span class="line"><span>which -s brew || ruby -e &quot;$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/master/install)&quot;</span></span>
<span class="line"><span>brew update</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Install dependencies</span></span>
<span class="line"><span>brew install git pkg-config python3 libpcap protobuf protobuf-c pcre librtlsdr libbtbb \\</span></span>
<span class="line"><span>ubertooth libusb openssl libwebsockets gpsd</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Clone and build Kismet</span></span>
<span class="line"><span>git clone https://www.kismetwireless.net/git/kismet.git</span></span>
<span class="line"><span>cd kismet</span></span>
<span class="line"><span>LDFLAGS=-L$(brew --prefix)/lib CPPFLAGS=&quot;-I$(brew --prefix)/include -I$(brew --prefix openssl)/include&quot; ./configure</span></span>
<span class="line"><span>make -j$(nproc)</span></span>
<span class="line"><span>sudo usermod -aG kismet $USER</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><h3 id="network-interface-card-nic-configuration" tabindex="-1">Network Interface Card (NIC) Configuration <a class="header-anchor" href="#network-interface-card-nic-configuration" aria-label="Permalink to &quot;Network Interface Card (NIC) Configuration&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. List available wireless interfaces</span></span>
<span class="line"><span>iwconfig</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Edit Kismet configuration</span></span>
<span class="line"><span>cd kismet</span></span>
<span class="line"><span>nano kismet.conf</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="gps-adapter" tabindex="-1">GPS Adapter <a class="header-anchor" href="#gps-adapter" aria-label="Permalink to &quot;GPS Adapter&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>gps=true</span></span>
<span class="line"><span>gpsd=true</span></span>
<span class="line"><span>gpsd-host=localhost</span></span>
<span class="line"><span>gpsd-port=2947</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="wireless-adapter" tabindex="-1">Wireless Adapter <a class="header-anchor" href="#wireless-adapter" aria-label="Permalink to &quot;Wireless Adapter&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>ncsource=wlan0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to &quot;Logging&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>logtypes=pcapdump,netxml</span></span>
<span class="line"><span>logtemplate=%n-%d-%i.%l</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="web-ui" tabindex="-1">Web UI <a class="header-anchor" href="#web-ui" aria-label="Permalink to &quot;Web UI&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>web=true</span></span>
<span class="line"><span>webport=2501</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="remote-capture" tabindex="-1">Remote Capture <a class="header-anchor" href="#remote-capture" aria-label="Permalink to &quot;Remote Capture&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>remote=true</span></span>
<span class="line"><span>remotesource=wlan0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>plugins=alert_log,db-log,db-sqlite,db-geoip</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="alerts" tabindex="-1">Alerts <a class="header-anchor" href="#alerts" aria-label="Permalink to &quot;Alerts&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>alerts=alert_log,alert_syslog,alert_screens,alert_webhook</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="running-kismet" tabindex="-1">Running Kismet <a class="header-anchor" href="#running-kismet" aria-label="Permalink to &quot;Running Kismet&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. Run Kismet</span></span>
<span class="line"><span>./kismet</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Common options</span></span>
<span class="line"><span>-c &lt;config file&gt;   # Specify a config file</span></span>
<span class="line"><span>-n                 # Don&#39;t start the UI</span></span>
<span class="line"><span>-f &lt;log file&gt;      # Log to a file</span></span>
<span class="line"><span>-t &lt;log type&gt;      # Log to a specific type</span></span>
<span class="line"><span>-l &lt;log level&gt;     # Log at a specific level</span></span>
<span class="line"><span>-p &lt;plugin&gt;        # Load a specific plugin</span></span>
<span class="line"><span>-u &lt;user&gt;          # Run as a specific user</span></span>
<span class="line"><span>-w &lt;work dir&gt;      # Specify a working directory</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><h3 id="gpsd-error" tabindex="-1">GPSD Error <a class="header-anchor" href="#gpsd-error" aria-label="Permalink to &quot;GPSD Error&quot;">​</a></h3><h4 id="linux-1" tabindex="-1">Linux <a class="header-anchor" href="#linux-1" aria-label="Permalink to &quot;Linux&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>sudo apt install gpsd gpsd-clients</span></span>
<span class="line"><span>sudo systemctl start gpsd</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h4 id="macos-1" tabindex="-1">macOS <a class="header-anchor" href="#macos-1" aria-label="Permalink to &quot;macOS&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>brew install gpsd</span></span>
<span class="line"><span>gpsd -N -D 2 /dev/ttyUSB0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="usb-error" tabindex="-1">USB Error <a class="header-anchor" href="#usb-error" aria-label="Permalink to &quot;USB Error&quot;">​</a></h3><h4 id="linux-2" tabindex="-1">Linux <a class="header-anchor" href="#linux-2" aria-label="Permalink to &quot;Linux&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>sudo usermod -aG kismet $USER</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h4 id="macos-2" tabindex="-1">macOS <a class="header-anchor" href="#macos-2" aria-label="Permalink to &quot;macOS&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>sudo dseditgroup -o edit -a $USER -t user kismet</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="faqs" tabindex="-1">FAQs <a class="header-anchor" href="#faqs" aria-label="Permalink to &quot;FAQs&quot;">​</a></h3><h3 id="how-do-i-add-an-sdr-as-a-data-source-in-kismet" tabindex="-1">How do I add an SDR as a data source in Kismet? <a class="header-anchor" href="#how-do-i-add-an-sdr-as-a-data-source-in-kismet" aria-label="Permalink to &quot;How do I add an SDR as a data source in Kismet?&quot;">​</a></h3><p>Ensure SDR drivers are properly installed and add the appropriate SDR configuration to the Kismet data source settings.</p><h3 id="why-is-my-gps-not-providing-accurate-data-to-kismet" tabindex="-1">Why is my GPS not providing accurate data to Kismet? <a class="header-anchor" href="#why-is-my-gps-not-providing-accurate-data-to-kismet" aria-label="Permalink to &quot;Why is my GPS not providing accurate data to Kismet?&quot;">​</a></h3><p>Ensure your GPS device is correctly installed and has a clear line of sight to the sky. Use <code>gpsd</code> and tools like <code>cgps</code> to verify operation.</p><h3 id="can-i-use-kismet-for-wardriving" tabindex="-1">Can I use Kismet for wardriving? <a class="header-anchor" href="#can-i-use-kismet-for-wardriving" aria-label="Permalink to &quot;Can I use Kismet for wardriving?&quot;">​</a></h3><p>Yes. Configure Kismet to log data to disk, integrate GPS for location data, and use optimized wardriving settings.</p><h3 id="how-can-i-improve-the-capture-range-of-my-sdr" tabindex="-1">How can I improve the capture range of my SDR? <a class="header-anchor" href="#how-can-i-improve-the-capture-range-of-my-sdr" aria-label="Permalink to &quot;How can I improve the capture range of my SDR?&quot;">​</a></h3><p>Optimize SDR gain settings and use high-quality antennas for your frequency range.</p><h3 id="can-kismet-monitor-bluetooth-devices" tabindex="-1">Can Kismet monitor Bluetooth devices? <a class="header-anchor" href="#can-kismet-monitor-bluetooth-devices" aria-label="Permalink to &quot;Can Kismet monitor Bluetooth devices?&quot;">​</a></h3><p>Yes. Use compatible Bluetooth interfaces and configure them in Kismet as data sources.</p><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><ul><li><p><a href="https://www.kismetwireless.net/" target="_blank" rel="noreferrer">Kismet Official Site</a></p></li><li><p><a href="https://www.kismetwireless.net/docs/readme/intro/#passive-monitoring" target="_blank" rel="noreferrer">Passive Monitoring</a></p></li><li><p><a href="https://www.kismetwireless.net/docs/readme/quickstart/#compiling-quick-setup" target="_blank" rel="noreferrer">Quickstart Guide</a></p></li></ul><p>[Installation]</p>`,56)])])}const h=s(l,[["render",p]]);export{b as __pageData,h as default};
